import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture } from 'three/tsl';
import { gsap } from 'gsap';
import {} from '@/primitives';
import {} from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;
  const container = new Group();

  // --- Geometry --------------------------------------------------------------
  const atlasRect = config.atlasRegion?.sourceRect || { width: 512, height: 320 };
  const aspect = atlasRect.width / atlasRect.height;
  const geometry = new PlaneGeometry(aspect, 1);

  // --- Material ---------------------------------------------------------------
  const material = new MeshBasicNodeMaterial();
  material.transparent = true;

  // Load texture asynchronously, but apply when ready
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    material.map = texture(tex);
    material.needsUpdate = true;
  });

  // --- Mesh -------------------------------------------------------------------
  const mesh = new Mesh(geometry, material);
  // Billboard behaviour
  mesh.onBeforeRender = (_renderer, _scene, camera) => {
    mesh.quaternion.copy(camera.quaternion);
  };
  container.add(mesh);

  // --- Cinematic Primitives ---------------------------------------------------
  const primitiveInstances = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const instance = ctx.primitives[prim.name](container, prim.params);
      primitiveInstances.push(instance);
    }
  }

  // --- Event Handlers placeholder ---------------------------------------------
  container.userData.handlers = {};

  // --- Cleanup ---------------------------------------------------------------
  container.userData.cleanup = () => {
    // Dispose material and geometry
    if (material.map) {
      const tex = material.map.value?.value || material.map;
      if (tex && typeof tex.dispose === 'function') tex.dispose();
    }
    material.dispose();
    geometry.dispose();

    // Kill any GSAP timelines (none in this node, but guard for future)
    if (Array.isArray(primitiveInstances)) {
      for (const inst of primitiveInstances) {
        if (inst && typeof inst.cleanup === 'function') inst.cleanup();
      }
    }
    gsap.killTweensOf(container);
  };

  return container;
}
